local JSON = require "cjson" local bit = require "bit" local CONSTANT = {          BYTE_DEVICE_TYPE = 0x32,          BYTE_MSG_TYPE_CONTROL = 0x02,          BYTE_MSG_TYPE_QUERY = 0x03,          BYTE_PROTOCOL_HEAD = 0xAA,          BYTE_PROTOCOL_HEAD_LENGTH = 0x0A, } local function string2Int(data)     if (not data) then         data = tonumber("0")     end     data = tonumber(data)     if (data == nil) then         data = 0     end     return data end local function table2string(cmd)     local ret = ""     local i     for i = 1, #cmd do         ret = ret .. string.char(cmd[i])     end     return ret end local function string2table(hexstr)     local tb = {}     local i = 1     local j = 1     for i = 1, #hexstr - 1, 2 do         local doublebytestr = string.sub(hexstr, i, i + 1)         tb[j] = tonumber(doublebytestr, 16)         j = j + 1     end     return tb end local function string2hexstring(str)     local ret = ""     for i = 1, #str do         ret = ret .. string.format("%02x", str:byte(i))     end     return ret end local function makeSum(tmpbuf, start_pos, end_pos)     local resVal = 0     for si = start_pos, end_pos do         resVal = resVal + tmpbuf[si]     end     resVal = bit.bnot(resVal) + 1     resVal = bit.band(resVal, 0x00FF)     return resVal end local function splitStrByChar(str, sepChar)     local splitList = {}     local pattern = '[^' .. sepChar .. ']+'     string.gsub(str, pattern, function(w)         table.insert(splitList, w)     end)     return splitList end local function getTotalMsg(bodyData, cType)     local bodyLength = #bodyData + 1     local msgLength = bodyLength + CONSTANT["BYTE_PROTOCOL_HEAD_LENGTH"] + 1     local msgBytes = {}     for i = 0, msgLength - 1 do         msgBytes[i] = 0     end          msgBytes[0] = CONSTANT["BYTE_PROTOCOL_HEAD"]     msgBytes[1] = msgLength - 1     msgBytes[2] = CONSTANT["BYTE_DEVICE_TYPE"]     msgBytes[8] = 0x00     msgBytes[9] = cType          for i = 0, bodyLength - 1 do         msgBytes[i + CONSTANT["BYTE_PROTOCOL_HEAD_LENGTH"]] = bodyData[i]     end     msgBytes[msgLength - 1] = makeSum(msgBytes, 1, msgLength - 2)          local msgFinal = {}     for i = 1, msgLength do         msgFinal[i] = msgBytes[i - 1]     end     return msgFinal end local function jsonToModel(jsonCmd)     local streams = jsonCmd          if (streams["controlSrc"] == nil) then         streams["controlSrc"] = streams["control_src"]     end     if (streams["subCmd"] == nil) then         streams["subCmd"] = streams["sub_cmd"]     end          local controlSrc = streams["controlSrc"]     if (controlSrc ~= nil) then         if "self" == controlSrc then             streams["controlSrc"] = 0         elseif "mideaMeiju" == controlSrc then             streams["controlSrc"] = 1         elseif "tmallSpirit" == controlSrc then             streams["controlSrc"] = 2         elseif "jingdong" == controlSrc then             streams["controlSrc"] = 3         elseif "selfVoice" == controlSrc then             streams["controlSrc"] = 20         elseif "mideaMeijuVoice" == controlSrc then             streams["controlSrc"] = 21         elseif "tmallSpiritVoice" == controlSrc then             streams["controlSrc"] = 22         elseif "jingdongVoice" == controlSrc then             streams["controlSrc"] = 23         else             streams["controlSrc"] = 0         end     else         streams["controlSrc"] = 0     end          if (streams["subCmd"] == nil) then         streams["subCmd"] = 1     end          if (streams["runMode"] == nil) then         streams["runMode"] = 0     end          if streams["modifyTimeEnable"] == true then         streams["modifyTimeEnable"] = 1     else         streams["modifyTimeEnable"] = 0     end     if streams["modifyTempEnable"] == true then         streams["modifyTempEnable"] = 1     else         streams["modifyTempEnable"] = 0     end          local workSwitchStr = streams["workSwitch"]     if (workSwitchStr == "standby") then         streams["workSwitch"] = 0     elseif (workSwitchStr == "schedule") then         streams["workSwitch"] = 1     elseif (workSwitchStr == "work") then         streams["workSwitch"] = 2     elseif (workSwitchStr == "pause") then         streams["workSwitch"] = 3     elseif (workSwitchStr == "keepWork") then         streams["workSwitch"] = 4     elseif (workSwitchStr == "modifyParam") then         streams["workSwitch"] = 5     end     if (streams["time"] ~= nil) then                  if (streams["time"]["appointTimeSecond"] ~= nil) then             local temp = streams["time"]["appointTimeSecond"]             streams["appointTimeHour"] = math.modf(temp / 3600)             streams["appointTimeMinute"] = math.modf((temp - streams["appointTimeHour"] * 3600) / 60)             streams["appointTimeSecond"] = temp - streams["appointTimeHour"] * 3600 - streams["appointTimeMinute"] * 60         else             streams["appointTimeHour"] = 0             streams["appointTimeMinute"] = 0             streams["appointTimeSecond"] = 0         end                  if (streams["time"]["workTimeSecond"] ~= nil) then             local temp = streams["time"]["workTimeSecond"]             streams["workTimeHour"] = math.modf(temp / 3600)             streams["workTimeMinute"] = math.modf((temp - streams["workTimeHour"] * 3600) / 60)             streams["workTimeSecond"] = temp - streams["workTimeHour"] * 3600 - streams["workTimeMinute"] * 60         else             streams["workTimeHour"] = 0             streams["workTimeMinute"] = 0             streams["workTimeSecond"] = 0         end                  if (streams["time"]["keepWarmTimeSecond"] ~= nil) then             local temp = streams["time"]["keepWarmTimeSecond"]             streams["keepWarmTimeHour"] = math.modf(temp / 3600)             streams["keepWarmTimeMinute"] = math.modf((temp - streams["keepWarmTimeHour"] * 3600) / 60)             streams["keepWarmTimeSecond"] = temp - streams["keepWarmTimeHour"] * 3600 - streams["keepWarmTimeMinute"] * 60         else             streams["keepWarmTimeHour"] = 0             streams["keepWarmTimeMinute"] = 0             streams["keepWarmTimeSecond"] = 0         end     else         streams["appointTimeHour"] = 0         streams["appointTimeMinute"] = 0         streams["appointTimeSecond"] = 0         streams["workTimeHour"] = 0         streams["workTimeMinute"] = 0         streams["workTimeSecond"] = 0         streams["keepWarmTimeHour"] = 0         streams["keepWarmTimeMinute"] = 0         streams["keepWarmTimeSecond"] = 0     end          if (streams["targetTemperature"] == nil) then         streams["targetTemperature"] = 0     end          if (streams["diyTotalStep"] == nil) then         streams["diyTotalStep"] = 0     end          local foodType = streams["foodType"]     if (foodType ~= nil) then         if "cupCubilose" == foodType then             streams["foodType"] = 1         elseif "cornerCubilose" == foodType then             streams["foodType"] = 2         elseif "stripCubilose" == foodType then             streams["foodType"] = 3         elseif "shredCubilose" == foodType then             streams["foodType"] = 4         else             streams["foodType"] = 0         end     else         streams["foodType"] = 0     end     return streams end local function binToModel(binData, dataType, subCmd)     if (#binData < 10) then         return nil     end     local streams = {}     local messageBytes = binData     if (dataType == 0x02 and (subCmd == 0x02 or subCmd == 0x04 or subCmd == 0x06))             or (dataType == 0x03 and subCmd == 0x02)             or (dataType == 0x04 and subCmd == 0x02) then                  streams["commonProtocolVersion"] = messageBytes[2]         streams["protocolVersion"] = messageBytes[3]         streams["ackType"] = messageBytes[4]         streams["controlSrc"] = messageBytes[5]         if messageBytes[5] == 0 then             streams["controlSrc"] = "self"         elseif messageBytes[5] == 1 then             streams["controlSrc"] = "mideaMeiju"         elseif messageBytes[5] == 2 then             streams["controlSrc"] = "tmallSpirit"         elseif messageBytes[5] == 3 then             streams["controlSrc"] = "jingdong"         elseif messageBytes[5] == 20 then             streams["controlSrc"] = "selfVoice"         elseif messageBytes[5] == 21 then             streams["controlSrc"] = "mideaMeijuVoice"         elseif messageBytes[5] == 22 then             streams["controlSrc"] = "tmallSpiritVoice"         elseif messageBytes[5] == 23 then             streams["controlSrc"] = "jingdongVoice"         end                  streams["runMode"] = messageBytes[7] + messageBytes[8] * 256 + messageBytes[9] * 65536 + messageBytes[10] * 16777216                  streams["workStatus"] = messageBytes[11]         if messageBytes[11] == 0 then             streams["workStatus"] = "standby"         elseif messageBytes[11] == 1 then             streams["workStatus"] = "schedule"         elseif messageBytes[11] == 2 then             streams["workStatus"] = "working"         elseif messageBytes[11] == 3 then             streams["workStatus"] = "pause"         elseif messageBytes[11] == 4 then             streams["workStatus"] = "keepWarm"         elseif messageBytes[11] == 255 then             streams["workStatus"] = "error"         end                  streams["errorCode"] = messageBytes[12]                  local time = {}                  time["remainAppointTimeSecond"] = messageBytes[13] * 3600 + messageBytes[14] * 60 + messageBytes[15]                  time["remainWorkTimeSecond"] = messageBytes[16] * 3600 + messageBytes[17] * 60 + messageBytes[18]                  time["remainKeepWarmTimeSecond"] = messageBytes[19] * 3600 + messageBytes[20] * 60 + messageBytes[21]                  time["appointTimeSecond"] = messageBytes[22] * 3600 + messageBytes[23] * 60 + messageBytes[24]                  time["targetAppointTimeSecond"] = messageBytes[25] * 3600 + messageBytes[26] * 60 + messageBytes[27]                  time["workTimeSecond"] = messageBytes[28] * 3600 + messageBytes[29] * 60 + messageBytes[30]                  streams["subType"] = messageBytes[34]                  time["keepWarmTimeSecond"] = messageBytes[35] * 3600 + messageBytes[36] * 60 + messageBytes[37]                  time["alreadyKeepWarmTimeSecond"] = time["keepWarmTimeSecond"] - time["remainKeepWarmTimeSecond"]                  streams["workState"] = messageBytes[38]                  streams["targetTemperature"] = messageBytes[39]                  streams["currentTemperature"] = messageBytes[40]                           time["remainPauseTimeMinute"] = messageBytes[42]                  streams["time"] = time                  streams["waterShortageState"] = messageBytes[43]         if messageBytes[43] == 1 then             streams["waterShortageState"] = "waterShortage"         elseif messageBytes[43] == 0 then             streams["waterShortageState"] = "notWaterShortage"         end                  streams["diyTotalStep"] = messageBytes[44]                  streams["currWorkStep"] = messageBytes[45]                  streams["foodType"] = "invalid"         if messageBytes[46] == 1 then             streams["foodType"] = "cupCubilose"         elseif messageBytes[46] == 2 then             streams["foodType"] = "cornerCubilose"         elseif messageBytes[46] == 3 then             streams["foodType"] = "stripCubilose"         elseif messageBytes[46] == 4 then             streams["foodType"] = "shredCubilose"         end     else                  streams["commonProtocolVersion"] = 0         streams["protocolVersion"] = 0         streams["ackType"] = 0         streams["controlSrc"] = "self"                  streams["runMode"] = 0                  streams["workStatus"] = 0                  streams["errorCode"] = 0                  local time = {}                  time["remainAppointTimeSecond"] = 0                  time["remainWorkTimeSecond"] = 0                  time["remainKeepWarmTimeSecond"] = 0                  time["appointTimeSecond"] = 0                  time["targetAppointTimeSecond"] = 0                  time["workTimeSecond"] = 0                  streams["subType"] = 0                  time["keepWarmTimeSecond"] = 0                  streams["workState"] = 0                  streams["targetTemperature"] = 0                  streams["currentTemperature"] = 0                           time["remainPauseTimeMinute"] = 0                  streams["time"] = time                  streams["waterShortageState"] = "notWaterShortage"                  streams["diyTotalStep"] = 0                  streams["currWorkStep"] = 0                  streams["foodType"] = "invalid"     end     return streams end function jsonToData(jsonCmd)     if (#jsonCmd == 0 or #jsonCmd == 2) then         return nil     end     local infoM = {}     local bodyBytes = {}     local json = JSON.decode(jsonCmd)     local query = json["query"]     local control = json["control"]     if (query) then         jsonToModel(query)         for i = 0, 6 do             bodyBytes[i] = 0         end         bodyBytes[0] = 0xAA         bodyBytes[1] = 0x55         bodyBytes[3] = 0x01         infoM = getTotalMsg(bodyBytes, CONSTANT["BYTE_MSG_TYPE_QUERY"])     elseif (control) then                  if control.recipe_cmd ~= nil then             return control.recipe_cmd         end         control = jsonToModel(control)                  if (control["subCmd"] == 1 or control["subCmd"] == 5) then             for i = 0, 28 do                 bodyBytes[i] = 0             end             bodyBytes[0] = 0xAA             bodyBytes[1] = 0x55             bodyBytes[2] = control["controlSrc"]             bodyBytes[3] = control["subCmd"]                          bodyBytes[4] = bit.band(control["runMode"], 0xFF)             bodyBytes[5] = bit.band(bit.rshift(control["runMode"], 8), 0xFF)             bodyBytes[6] = bit.band(bit.rshift(control["runMode"], 16), 0xFF)             bodyBytes[7] = bit.band(bit.rshift(control["runMode"], 24), 0xFF)                          bodyBytes[8] = control["workSwitch"]                          bodyBytes[9] = control["appointTimeHour"]                          bodyBytes[10] = control["appointTimeMinute"]                          bodyBytes[11] = control["appointTimeSecond"]                          bodyBytes[12] = control["workTimeHour"]                          bodyBytes[13] = control["workTimeMinute"]                          bodyBytes[14] = control["workTimeSecond"]                          bodyBytes[20] = control["targetTemperature"]                          bodyBytes[21] = bit.bor(bit.lshift(bit.band(control["modifyTimeEnable"], 0x01), 7), bit.lshift(bit.band(control["modifyTempEnable"], 0x01), 6))                          bodyBytes[22] = control["keepWarmTimeHour"]                          bodyBytes[23] = control["keepWarmTimeMinute"]                          bodyBytes[24] = control["keepWarmTimeSecond"]                          bodyBytes[25] = control["foodType"]             infoM = getTotalMsg(bodyBytes, CONSTANT["BYTE_MSG_TYPE_CONTROL"])         elseif (control["subCmd"] == 3) then                          for i = 0, 59 do                 bodyBytes[i] = 0             end             bodyBytes[0] = 0xAA             bodyBytes[1] = 0x55             bodyBytes[2] = control["controlSrc"]             bodyBytes[3] = control["subCmd"]                          bodyBytes[4] = bit.band(control["runMode"], 0xFF)             bodyBytes[5] = bit.band(bit.rshift(control["runMode"], 8), 0xFF)             bodyBytes[6] = bit.band(bit.rshift(control["runMode"], 16), 0xFF)             bodyBytes[7] = bit.band(bit.rshift(control["runMode"], 24), 0xFF)                          bodyBytes[8] = control["workSwitch"]                          bodyBytes[9] = control["appointTimeHour"]                          bodyBytes[10] = control["appointTimeMinute"]                          bodyBytes[11] = control["appointTimeSecond"]                          bodyBytes[12] = control["workTimeHour"]                          bodyBytes[13] = control["workTimeMinute"]                          bodyBytes[14] = control["workTimeSecond"]                          bodyBytes[20] = control["targetTemperature"]                          bodyBytes[21] = bit.bor(bit.lshift(bit.band(control["modifyTimeEnable"], 0x01), 7), bit.lshift(bit.band(control["modifyTempEnable"], 0x01), 6))                          bodyBytes[22] = control["keepWarmTimeHour"]                          bodyBytes[23] = control["keepWarmTimeMinute"]                          bodyBytes[24] = control["keepWarmTimeSecond"]                          bodyBytes[29] = control["diyTotalStep"]             if (control["diyParams"] ~= nil) then                                  local tempList = splitStrByChar(control["diyParams"], "|")                 bodyBytes[29] = #tempList                 local j = 29                 for i = 1, #tempList do                     local param = splitStrByChar(tempList[i], ",")                                          bodyBytes[j + 1] = bit.band(string2Int(param[1]), 0xFF)                     bodyBytes[j + 2] = bit.band(bit.rshift(string2Int(param[1]), 8), 0xFF)                                          local workTimeTemp = string2Int(param[2])                                          workTimeTemp = math.modf(workTimeTemp / 60)                     bodyBytes[j + 3] = bit.band(workTimeTemp, 0xFF)                     bodyBytes[j + 4] = bit.band(bit.rshift(workTimeTemp, 8), 0xFF)                                          local tempTime = string2Int(param[3])                     if (tempTime ~= nil) then                         bodyBytes[22] = math.modf(tempTime / 3600)                         bodyBytes[23] = math.modf((tempTime - bodyBytes[22] * 3600) / 60)                         bodyBytes[24] = tempTime - bodyBytes[22] * 3600 - bodyBytes[23] * 60                     else                         bodyBytes[22] = 0                         bodyBytes[23] = 0                         bodyBytes[24] = 0                     end                     j = j + 6                 end             end             infoM = getTotalMsg(bodyBytes, CONSTANT["BYTE_MSG_TYPE_CONTROL"])         end     end     local ret = table2string(infoM)     ret = string2hexstring(ret)     return ret end function dataToJson(jsonCmd)     if (not jsonCmd) then         return nil     end     local json = JSON.decode(jsonCmd)     local binData = json["msg"]["data"]     local info = {}     local msgBytes = {}     local bodyBytes = {}     local msgLength = 0     local bodyLength = 0     info = string2table(binData)     for i = 1, #info do         msgBytes[i - 1] = info[i]     end     msgLength = msgBytes[1] + 1     bodyLength = msgLength - CONSTANT["BYTE_PROTOCOL_HEAD_LENGTH"] - 1     for i = 0, bodyLength - 1 do         bodyBytes[i] = msgBytes[i + CONSTANT["BYTE_PROTOCOL_HEAD_LENGTH"]]     end     local retTable = {}     local streams = binToModel(bodyBytes, info[10], info[17])     if (info[10] == 4 and info[17] == 6) then     else         streams["dataType"] = info[10]         streams["subCmd"] = info[17]         retTable["status"] = streams         local ret = JSON.encode(retTable)         return ret     end end

-- ============================================================
-- Home Assistant wrapper (midea_smart_home custom lua)
-- 1) dataToJson: flatten nested status.time.* into top-level keys
-- 2) jsonToData: translate flat *TimeMinutes control keys into
--    the nested "time" object expected by jsonToModel
-- ============================================================
local __orig_jsonToData = jsonToData
local __orig_dataToJson = dataToJson

function jsonToData(jsonCmd)
    if jsonCmd ~= nil and #jsonCmd > 2 then
        local ok, json = pcall(JSON.decode, jsonCmd)
        if ok and type(json) == "table" and type(json.control) == "table" then
            local c = json.control
            local t = c.time
            local changed = false
            if type(t) ~= "table" then
                t = {}
            end
            if c.workTimeMinutes ~= nil then
                t.workTimeSecond = tonumber(c.workTimeMinutes) * 60
                c.workTimeMinutes = nil
                changed = true
            end
            if c.appointTimeMinutes ~= nil then
                t.appointTimeSecond = tonumber(c.appointTimeMinutes) * 60
                c.appointTimeMinutes = nil
                changed = true
            end
            if c.keepWarmTimeMinutes ~= nil then
                t.keepWarmTimeSecond = tonumber(c.keepWarmTimeMinutes) * 60
                c.keepWarmTimeMinutes = nil
                changed = true
            end
            if changed then
                c.time = t
                jsonCmd = JSON.encode(json)
            end
        end
    end
    return __orig_jsonToData(jsonCmd)
end

function dataToJson(jsonCmd)
    local ret = __orig_dataToJson(jsonCmd)
    if ret == nil then
        return nil
    end
    local ok, tbl = pcall(JSON.decode, ret)
    if ok and type(tbl) == "table" and type(tbl.status) == "table" then
        local s = tbl.status
        if type(s.time) == "table" then
            for k, v in pairs(s.time) do
                s[k] = v
            end
            s.time = nil
            ret = JSON.encode(tbl)
        end
    end
    return ret
end
